```cpp
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

long long reflect(long long n) {
    string s = to_string(n);
    for (int i = 0; i < s.size(); i++) {
        s[i] = '9' - s[i] + '0';
    }
    // Remove leading zeros
    int start = 0;
    while (start < s.size() && s[start] == '0') start++;
    if (start == s.size()) return 0;
    return stoll(s.substr(start));
}

int main() {
    long long l, r;
    cin >> l >> r;
    long long max_prod = 0;
    for (long long n = l; n <= r; n++) {
        long long refl = reflect(n);
        max_prod = max(max_prod, n * refl);
    }
    cout << max_prod << endl;
    return 0;
}
